"""Validate selected point claims without constructing or publishing a map."""
SUPPORTED={'source_point_component_v1','source_point_named_region_component_v1','raw_json_city_named_region_component_v1','osm_api_node_named_region_component_v1','osm_api_island_node_group_component_v1','geonames_zip_island_named_region_component_v1','geonames_zip_airport_named_region_component_v1','geonames_zip_named_island_component_v1'}
def need(v,m):
 if not v: raise ValueError(m)

def claims_for(compiled,snapshot,resolution):
 aff={x['affiliation_id']:x for x in snapshot['affiliations']};bindings={b['entity_id']:b['code'] for b in snapshot['category_bindings'] if b.get('physical_class')=='land'}
 need(resolution.get('schema')=='source-point-component-report-v1' and resolution.get('status')=='research-only-not-a-build' and resolution.get('revision')==compiled['revision'] and resolution.get('entity_revision')==compiled['entity_revision'],'point resolution identity mismatch')
 claims=resolution.get('claims');need(isinstance(claims,list) and len(claims)==len(compiled['affiliation_ids']),'point claim count mismatch');roots={};seen=set()
 for c in claims:
  aid=c.get('affiliation_id');need(aid in aff and aid not in seen and aid in compiled['affiliation_ids'],'unknown or duplicate claim');a=aff[aid];root=c.get('component_id');code=bindings.get(a.get('entity_id'))
  need(c.get('method')==a.get('method') and c.get('method') in SUPPORTED and c.get('entity_id')==a.get('entity_id') and c.get('entity_code')==code and type(root) is int and 0<=root<0xffffffff,'claim/decision mismatch')
  if c['method']=='raw_json_city_named_region_component_v1':
   feats={x['feature_id']:x for x in snapshot.get('features',[])};feature=feats.get(a.get('feature_id'),{});evidence=a.get('evidence',{});sel=evidence.get('selector',{});ext=c.get('raw_city_extraction') or {};ge=c.get('coordinate_guideline_evidence') or {};refs=[x for x in snapshot.get('affiliation_source_refs',[]) if x.get('affiliation_id')==aid and x.get('role')=='coordinate_guideline'];need(len(refs)==1,'guideline reference missing or duplicate');ref=refs[0]
   assets=[x for x in snapshot.get('source_lineage_assets',[]) if (x.get('source_id'),x.get('version'))==(ref.get('source_id'),ref.get('source_version'))];need(len(assets)==1,'guideline asset missing or duplicate');asset=assets[0];point_assets=[x for x in snapshot.get('source_lineage_assets',[]) if (x.get('source_id'),x.get('version'))==(feature.get('source_id'),feature.get('source_version'))];need(len(point_assets)==1,'city asset missing or duplicate');point_asset=point_assets[0];point_trace=c.get('point_source') or {}
   need(ext.get('source_sha256')==point_asset.get('sha256')==point_trace.get('sha256') and point_trace.get('source_id')==feature.get('source_id') and point_trace.get('version')==feature.get('source_version'),'city source binding mismatch')
   need(ext.get('schema')=='raw-json-city-point-extraction-v1' and ext.get('record_id')==feature.get('source_feature_id') and ext.get('record_name')==sel.get('point_name') and ext.get('geometry_sha256')==feature.get('geometry_sha256') and ext.get('source_crs_assertion')==sel.get('source_crs_assertion')=='OGC:CRS84' and c.get('source_crs_scope')=='raw_record_coordinate_assertion','raw city extraction/decision mismatch')
   need(ge.get('source_id')==ref['source_id'] and ge.get('version')==ref['source_version'] and ge.get('sha256')==asset.get('sha256') and ge.get('uri')==asset.get('source_uri') and ge.get('selected_excerpt')==sel.get('coordinate_guideline_excerpt') and ge.get('matches')==1 and c.get('identity_check',{}).get('strict_contains') is True,'guideline or identity evidence mismatch')
  if c['method'] in ('osm_api_node_named_region_component_v1','osm_api_island_node_group_component_v1'):
   feats={x['feature_id']:x for x in snapshot.get('features',[])};feature=feats.get(a.get('feature_id'),{});sel=a.get('evidence',{}).get('selector',{});ext=c.get('osm_node_extraction') or {};point_trace=c.get('point_source') or {};assets=[x for x in snapshot.get('source_lineage_assets',[]) if (x.get('source_id'),x.get('version'))==(feature.get('source_id'),feature.get('source_version'))];need(len(assets)==1,'OSM node asset missing or duplicate');asset=assets[0]
   need(ext.get('source_sha256')==asset.get('sha256')==point_trace.get('sha256') and point_trace.get('source_id')==feature.get('source_id') and point_trace.get('version')==feature.get('source_version'),'OSM node source binding mismatch')
   need(ext.get('schema')=='osm-api-node-point-extraction-v1' and ext.get('node_id')==feature.get('source_feature_id') and ext.get('node_version')==sel.get('node_version') and ext.get('verified_tags')=={'name':sel.get('island_name') if c['method']=='osm_api_island_node_group_component_v1' else sel.get('point_name'),'place':sel.get('place_tag')} and ext.get('source_crs')==sel.get('source_crs')=='OGC:CRS84' and ext.get('geometry_sha256')==feature.get('geometry_sha256') and c.get('source_crs_scope')=='osm_api_0_6_standard' and c.get('identity_check',{}).get('strict_contains') is True,'OSM node extraction/decision mismatch')
  if c['method']=='geonames_zip_airport_named_region_component_v1':
   feats={x['feature_id']:x for x in snapshot.get('features',[])};feature=feats.get(a.get('feature_id'),{});sel=a.get('evidence',{}).get('selector',{});ext=c.get('geonames_extraction') or {};point_trace=c.get('point_source') or {};assets=[x for x in snapshot.get('source_lineage_assets',[]) if (x.get('source_id'),x.get('version'))==(feature.get('source_id'),feature.get('source_version'))];need(len(assets)==1,'GeoNames airport asset missing or duplicate');asset=assets[0]
   need(ext.get('source_sha256')==asset.get('sha256')==point_trace.get('sha256') and point_trace.get('source_id')==feature.get('source_id') and point_trace.get('version')==feature.get('source_version'),'GeoNames airport source binding mismatch')
   need(sel.get('extractor_version')=='geonames-airport-point-extraction-v1' and sel.get('id_property')=='geonameid' and ext.get('schema')==sel['extractor_version'] and ext.get('record_id')==feature.get('source_feature_id') and ext.get('name')==sel.get('point_name') and ext.get('feature_class')=='S' and ext.get('feature_code')=='AIRP' and ext.get('country_code')==sel.get('country_code') and ext.get('geometry_sha256')==feature.get('geometry_sha256') and ext.get('source_crs')=='OGC:CRS84' and c.get('source_crs_scope')=='geonames_wgs84_record' and c.get('identity_check',{}).get('strict_contains') is True,'GeoNames airport extraction/decision mismatch')
   entries=compiled.get('affiliation_entry_links',{}).get(aid,[]);links=[l for l in snapshot.get('list1_entry_evidence_sources',[]) if l.get('entry_id') in entries and l.get('decision_revision')==compiled['revision'] and l.get('role')=='geographic_membership_evidence' and l.get('source_id')==sel.get('island_evidence_source_id') and l.get('source_version')==sel.get('island_evidence_source_version') and l.get('citation_section')==sel.get('island_evidence_citation')];need(len(links)==1 and (sel['island_evidence_source_id'],sel['island_evidence_source_version'])!=(feature.get('source_id'),feature.get('source_version')),'airport island evidence missing or duplicate')
   evidence_key=(sel['island_evidence_source_id'],sel['island_evidence_source_version']);identity_source=c.get('identity_source') or {};evidence_assets=[x for x in snapshot.get('source_lineage_assets',[]) if (x.get('source_id'),x.get('version'))==evidence_key];need(len(evidence_assets)==1 and evidence_key!=(identity_source.get('source_id'),identity_source.get('version')),'airport island evidence asset missing or not independent')
   interpretation=links[0].get('interpretation');airport=sel.get('point_name');island=sel.get('airport_island_name');need(isinstance(interpretation,str) and isinstance(airport,str) and airport.strip() and isinstance(island,str) and island.strip() and airport.casefold() in interpretation.casefold() and island.casefold() in interpretation.casefold(),'airport island identity assertion missing')
  if c['method'] in ('geonames_zip_island_named_region_component_v1','geonames_zip_named_island_component_v1'):
   feats={x['feature_id']:x for x in snapshot.get('features',[])};feature=feats.get(a.get('feature_id'),{});sel=a.get('evidence',{}).get('selector',{});ext=c.get('geonames_extraction') or {};point_trace=c.get('point_source') or {};assets=[x for x in snapshot.get('source_lineage_assets',[]) if (x.get('source_id'),x.get('version'))==(feature.get('source_id'),feature.get('source_version'))];need(len(assets)==1,'GeoNames asset missing or duplicate');asset=assets[0]
   need(ext.get('source_sha256')==asset.get('sha256')==point_trace.get('sha256') and point_trace.get('source_id')==feature.get('source_id') and point_trace.get('version')==feature.get('source_version'),'GeoNames source binding mismatch')
   need(sel.get('extractor_version')=='geonames-island-point-extraction-v1' and sel.get('id_property')=='geonameid' and ext.get('schema')==sel['extractor_version'] and ext.get('record_id')==feature.get('source_feature_id') and ext.get('name')==sel.get('point_name') and ext.get('feature_class')=='T' and ext.get('feature_code')=='ISL' and ext.get('country_code')==sel.get('country_code') and ext.get('geometry_sha256')==feature.get('geometry_sha256') and ext.get('source_crs')=='OGC:CRS84' and c.get('source_crs_scope')=='geonames_wgs84_record' and (c.get('identity_check',{}).get('strict_contains') is True if c['method']=='geonames_zip_island_named_region_component_v1' else c.get('identity_check',{}).get('method')=='selected_named_island_decision'),'GeoNames extraction/decision mismatch')
   if c['method']=='geonames_zip_named_island_component_v1':
    entry_id=sel.get('decision_entry_id')
    check=c.get('identity_check') or {}
    entity=next((row for row in snapshot.get('entities',[]) if row.get('id')==a.get('entity_id')),{})
    need(check.get('decision_entry_id')==entry_id
         and entry_id in compiled['affiliation_entry_links'][aid]
         and c.get('entity_name')==entity.get('name')
         and sel.get('island_identity')==sel.get('point_name'),'named island claim/decision mismatch')
  if c['method']=='osm_api_island_node_group_component_v1':
   sel=a.get('evidence',{}).get('selector',{});check=c.get('identity_check') or {};need(sel.get('identity_scope')=='island_group' and sel.get('identity_class_value')=='Island group' and sel.get('place_tag')=='island' and c.get('identity_scope')==sel['identity_scope'] and c.get('island_identity')==sel.get('island_name') and c.get('point_name')==sel.get('island_name') and c.get('group_identity')==sel.get('group_identity') and check.get('identity_feature_class')=='Island group' and check.get('strict_contains') is True,'island/group identity mismatch')
  roots.setdefault(root,[]).append({'affiliation_id':aid,'entry_ids':compiled['affiliation_entry_links'][aid],'code':code});seen.add(aid)
 need(seen==set(compiled['affiliation_ids']),'unconsumed selected affiliation');return roots
